#include <vector>
#include <unordered_set>
#include <algorithm>

using namespace std;

class Solution {
public:
    int minimizeTheDifference(vector<vector<int>>& mat, int target) {
        unordered_set<int> sums = {0};
        for (auto& row : mat) {
            unordered_set<int> newSums;
            for (int x : row)
                for (int s : sums)
                    newSums.insert(x + s);
            if (newSums.size() > 10000) break;
            sums = move(newSums);
        }

        int res = INT_MAX;
        for (int s : sums)
            res = min(res, abs(s - target));
        return res;
    }
};
